/*
 * fpga_regs.h - Configurable fields of the FPGA's CNC and DM blocks.
 *
 * The implementation (fpga_regs.c) is GENERATED by gen_regs.py from
 * fpga_regs.csv, which in turn was extracted from the GUI's Form1.cs.
 */
#ifndef FPGA_REGS_H
#define FPGA_REGS_H

#include <stddef.h>
#include <stdint.h>

typedef struct {
  const char *block;      /* "cnc" or "dm"                      */
  const char *name;       /* e.g. "serial_enable"               */
  uint8_t     reg;        /* register index inside the block    */
  uint8_t     pos;        /* lowest bit of the field            */
  uint8_t     bits;       /* width of the field, in bits        */
  uint8_t     read_only;
  const char *desc;
} fpga_field_t;

extern const fpga_field_t fpga_fields[];
extern const size_t       fpga_fields_count;

/* Look up by block + name, case-insensitive. NULL if it does not exist. */
const fpga_field_t *fpga_find(const char *block, const char *name);

#endif /* FPGA_REGS_H */
